<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script></head><body>
<canvas id="stage"></canvas>
<div id="countdown" aria-hidden="true">3</div>

<div id="dock" role="toolbar" aria-label="Simulation Controls">
  <button id="btn-refire" type="button" aria-label="Re-fire" title="Re-fire">
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <path d="M21.5 2v6h-6M21.34 15.57a10 10 0 1 1-.57-8.38l5.67-5.19"/>
    </svg>
    <span>Re-fire</span>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <button id="btn-toggle" type="button" aria-label="Pause" title="Play / Pause">
    <svg id="icon-pause" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true">
      <rect x="6" y="4" width="4" height="16" rx="1"/>
      <rect x="14" y="4" width="4" height="16" rx="1"/>
    </svg>
    <svg id="icon-play" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true" style="display:none;">
      <path d="M8 5v14l11-7z"/>
    </svg>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <div id="speed-group" role="radiogroup" aria-label="Playback Speed">
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.25">0.25×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.5">0.5×</button>
    <button class="speed-pill is-active" type="button" role="radio" aria-checked="true" data-speed="1.0">1.0×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="2.0">2.0×</button>
  </div>
  <span class="dock-sep" aria-hidden="true"></span>
  <input id="scrubber" type="range" min="0" max="100" step="0.001" value="0" aria-label="Timeline Scrubber">
</div>
<script id="rampart-strategy">
function createStrategy(){
  const costs={bolt:50,cannon:90,flak:80};
  const layout=[[1,'"'cannon'],[12,'bolt'],[14,'flak'],[6,'cannon'],[11,'cannon'],[2,'cannon'],[7,'cannon'],[13,'cannon'],[8,'flak'],[4,'cannon'],[3,'cannon'],[9,'cannon'],[0,'cannon'],[10,'flak'],[5,'cannon'],[15,'flak']];
  return {
    plan(s){
      let gold=s.gold, actions=[], choices=[];
      for(let i=0;i<layout.length;i++){
        let [slot,type]=layout[i], t=s.slots[slot].turret;
        if(type==='bolt' && t && s.wave>=24 && gold>=160){
          actions.push({op:'sell',slot}); gold+=Math.floor(.7*t.spent); t=null;
        }
        if(slot===12 && s.wave>=24)type='cannon';
        const tier=t?t.tier:0;
        if(tier===3)continue;
        let rank=i+(tier===1?1.7:tier===2?5:0);
        if(type==='flak' && i===2 && s.wave<5)rank+=12;
        if(slot===12 && tier)rank+=18;
        choices.push({slot,type,tier,rank,price:costs[type]*(tier===2?2:1)});
      }
      choices.sort((a,b)=>a.rank-b.rank);
      for(const c of choices){
        if(c.price>gold)break;
        actions.push({op:c.tier?'upgrade':'build',slot:c.slot,type:c.type});gold-=c.price;
      }
      return actions;
    },
    target(t,cs){
      let best=-Infinity,id=cs[0].id, splash=t.type==='cannon'?90:t.type==='flak'?70:0;
      const damage=({cannon:[60,96,153],flak:[40,64,102],bolt:[26,41,65]})[t.type][t.tier-1];
      for(let i=0;i<cs.length;i++){
        let e=cs[i], v=0;
        for(let j=splash?0:i;j<(splash?cs.length:i+1);j++){
          const q=cs[j],dx=e.x-q.x,dy=e.y-q.y;
          if(dx*dx+dy*dy>splash*splash)continue;
          const hit=Math.max(1,damage-q.armor);
          v+=(Math.min(q.hp,hit)/damage+(q.hp<=hit?.48:0))*(1+300/(100+q.remaining))*(q.type==='mender'?1.45:1);
        }
        if(v>best){best=v;id=e.id;}
      }
      return id;
    }
  };
}
</script>
<script id=\"rampart-sim\">
function rampartSimulate(createStrategy, seed, maxTicks){
  const record=arguments[3], floor=Math.floor, strategy=createStrategy(),log=[];
  function mulberry32(a){return function(){a=(a+0x6D2B79F5)|0;let t=Math.imul(a"'^(a>>>15),1|a);t=(t+Math.imul(t''^(t>>>7),61|t))''^t;return(t''^(t>>>14))>>>0;};}
  const draw=mulberry32(seed),types=['"'grunt','runner','wisp','brute','splitter','mender','splitling'];
  const hp=[60,40,50,150,90,70,1],speed=[10,20,12,6,8,8,12],bounty=[4,4,6,9,6,7,1],leak=[1,1,2,3,2,2,1],first=[1,2,3,4,6,8],weight=[10,4,3,3,2,1];
  const guns=['bolt','cannon','frost','lance','flak'],cost=[50,90,70,120,80],damage=[26,60,10,180,40],period=[8,24,12,36,10],range=[300,260,240,360,320],splash=[0,90,0,0,70];
  const paths=[[[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]],[[0,6],[21,6],[21,11],[23,11]]];
  const slots=[[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]].map(([x,y],slot)=>({slot,x:100*x+50,y:100*y+50,turret:null}));
  let enemies=[],queue=[],tick=0,wave=0,baseHp=10,gold=250,id=0,fallTick=-1,m=1000,events=[];
  function gen(w){
    const n=first.filter(v=>v<=w).length,sum=weight.slice(0,n).reduce((a,b)=>a+b,0);
    return Array.from({length:4+floor(3*w/5)},()=>{let r=draw()%sum,k=0;while(r>=weight[k])r-=weight[k++];return k;});
  }
  let next=gen(1);
  function position(e){
    let p=e.progress,path=paths[e.air];e.remaining=(e.air?2600:4600)-p;
    for(let i=1;i<path.length;i++){
      const [x,y]=path[i-1],dx=path[i][0]-x,dy=path[i][1]-y,len=(Math.abs(dx)+Math.abs(dy))*100;
      if(p<=len){e.x=x*100+50+Math.sign(dx)*p;e.y=y*100+50+Math.sign(dy)*p;e.angle=dx?Math.sign(dx)*Math.PI/2:dy>0?0:Math.PI;return;}p-=len;
    }
  }
  function spawn(k,w,h,p=0){
    const e={id:++id,type:types[k],k,w,hp:h,maxHp:h,air:+(k===2),armor:k===0?floor(w/4):k===3?6+w:0,speed:speed[k],slowed:0,progress:p,age:0};position(e);enemies.push(e);
  }
  const view=({id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining})=>({id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining});
  const slotView=s=>({...s,turret:s.turret?{type:s.turret.type,tier:s.turret.tier,spent:s.turret.spent}:null});
  function fx(kind,x,y,extra={}){if(record)events.push({kind,x:x/100,z:y/100,...extra});}
  function emit(code,a,b){log.push([tick,code,a,b]);}
  function snapshot(){if(record)record({wave,gold,baseHp,next:next.map(k=>types[k]),slots:slots.map(slotView),enemies:enemies.map(e=>({...view(e),angle:e.angle})),events});}
  for(;tick<maxTicks;tick++){
    events=[];
    if(tick>=20 && (tick-20)%40===0){
      wave++;if(wave>1)m=floor(m*108/100);
      gold+=Math.min(50,floor(gold*5/100))+10+2*wave;
      const current=next;next=gen(wave+1);fx('wave',50,250);
      const actions=strategy.plan({tick,wave,gold,baseHp,slots:slots.map(slotView),enemies:enemies.map(view),nextWave:next.map(k=>types[k])});
      for(const a of (Array.isArray(actions)?actions:[]).slice(0,32)){
        if("'!a||!Number.isInteger(a.slot)||!slots[a.slot])continue;
        const s=slots[a.slot],t=s.turret,k=guns.indexOf(a.type);
        if(a.op==='"'build'&&"'!t&&k>=0&&gold>=cost[k]){s.turret={k,type:a.type,tier:1,spent:cost[k],cd:0,d:damage[k]};gold-=cost[k];emit('"'B',a.slot,k);}
        else if(a.op==='upgrade'&&t&&t.tier<3&&gold>=cost[t.k]*t.tier){const price=cost[t.k]*t.tier;gold-=price;t.spent+=price;t.tier++;t.d=floor(t.d*16/10);emit('U',a.slot,t.tier);}
        else if(a.op==='sell'&&t){gold+=floor(t.spent*70/100);s.turret=null;emit('S',a.slot,0);}
        else continue;
        fx(a.op,s.x,s.y);
      }
      current.forEach((k,i)=>queue.push({tick:tick+4*i,k,w:wave,h:floor(hp[k]*m/1000)}));queue.sort((a,b)=>a.tick-b.tick||a.w-b.w);
    }
    while(queue.length&&queue[0].tick===tick){const q=queue.shift();spawn(q.k,q.w,q.h);}
    for(let i=0;i<enemies.length;i++){
      const e=enemies[i];e.progress+=e.slowed?floor(e.speed*60/100):e.speed;position(e);
      if(e.remaining<=0){baseHp-=leak[e.k];emit('L',e.id,baseHp);fx('leak',2350,1150);enemies.splice(i--,1);
        if(baseHp<=0){fallTick=tick;emit('F',wave,0);fx('fall',2350,1150);break;}}
    }
    if(fallTick>=0){snapshot();break;}
    const near=(a,b,r)=>(a.x-b.x)**2+(a.y-b.y)**2<=r*r;
    for(const e of enemies){if(++e.age%20===0&&e.k===5){for(const q of enemies)if(near(e,q,150))q.hp=Math.min(q.maxHp,q.hp+floor(q.maxHp*8/100));fx('heal',e.x,e.y);}}
    for(const s of slots){
      const t=s.turret;if("'!t||(t.cd>0&&--t.cd>0))continue;
      const k=t.k,r=range[k]+30*(t.tier-1),valid=e=>e.air?k!==1&&k!==3:k!==4;
      const cs=enemies.filter(e=>valid(e)&&near(s,e,r));if(!cs.length)continue;
      const pick=strategy.target?.({slot:s.slot,type:t.type,tier:t.tier,x:s.x,y:s.y,range:r},cs.map(view));
      const dst=cs.find(e=>e.id===pick)||cs.reduce((a,b)=>b.remaining<a.remaining?b:a);
      fx('"'shot',s.x,s.y,{gun:k,slot:s.slot,tx:dst.x/100,tz:dst.y/100,air:dst.air});t.cd=period[k];
      for(const e of splash[k]?enemies:[dst])if(valid(e)&&near(e,dst,splash[k])){e.hp-=Math.max(1,t.d-(k===3?0:e.armor));if(k===2)e.slowed=30;}
      const dead=enemies.filter(e=>e.hp<=0);
      if(dead.length)enemies=enemies.filter(e=>e.hp>0);
      for(const e of dead){gold+=bounty[e.k];emit('K',e.id,s.slot);fx('kill',e.x,e.y,{k:e.k,id:e.id});
        if(e.k===4)for(let i=0;i<3;i++)spawn(6,e.w,Math.max(1,floor(e.maxHp/4)),e.progress);}
    }
    for(const e of enemies)if(e.slowed)e.slowed--;snapshot();
  }
  let h=0x811c9dc5;const str=JSON.stringify(log);for(let i=0;i<str.length;i++)h=Math.imul(h"'^str.charCodeAt(i),0x01000193);
  return {score:Math.round((tick-20)/40*100)/100,fallTick,log,hash:(h>>>0).toString(16).padStart(8,'"'0')};
}
</script>
